// The Sun, the eight planets and the Moon, with what the 3D scene needs.
// longitude_j2000_deg is where each planet was along its orbit on 1 January 2000,
// so together with the orbital period the scene can place it on any date.
const bodies = [
  { name: 'Sun', type: 'star', radius_km: 696340, distance_au: 0, orbital_period_days: 0, rotation_period_hours: 609.1, axial_tilt_deg: 7.25, longitude_j2000_deg: 0, colour: '#ffcc33', fact: 'It holds about 99.8% of all the mass in the Solar System.' },
  { name: 'Mercury', type: 'planet', radius_km: 2440, distance_au: 0.387, orbital_period_days: 87.97, rotation_period_hours: 1407.6, axial_tilt_deg: 0.03, longitude_j2000_deg: 252.25, colour: '#a6a6a6', fact: 'From one sunrise to the next takes two of its years.' },
  { name: 'Venus', type: 'planet', radius_km: 6052, distance_au: 0.723, orbital_period_days: 224.7, rotation_period_hours: -5832.5, axial_tilt_deg: 177.4, longitude_j2000_deg: 181.98, colour: '#e8c27a', fact: 'The hottest planet, at about 465 °C, even though Mercury is closer to the Sun.' },
  { name: 'Earth', type: 'planet', radius_km: 6371, distance_au: 1.0, orbital_period_days: 365.26, rotation_period_hours: 23.93, axial_tilt_deg: 23.44, longitude_j2000_deg: 100.46, colour: '#3b82f6', fact: 'The only planet known to have liquid water on its surface.' },
  { name: 'Moon', type: 'moon', parent: 'Earth', radius_km: 1737, distance_au: 0.00257, orbital_period_days: 27.32, rotation_period_hours: 655.7, axial_tilt_deg: 6.68, longitude_j2000_deg: 0, colour: '#cfcfcf', fact: 'It drifts about 3.8 cm further from Earth every year.' },
  { name: 'Mars', type: 'planet', radius_km: 3390, distance_au: 1.524, orbital_period_days: 686.98, rotation_period_hours: 24.62, axial_tilt_deg: 25.19, longitude_j2000_deg: 355.45, colour: '#c1440e', fact: 'Home to Olympus Mons, a volcano about 22 km high.' },
  { name: 'Jupiter', type: 'planet', radius_km: 69911, distance_au: 5.203, orbital_period_days: 4332.59, rotation_period_hours: 9.93, axial_tilt_deg: 3.13, longitude_j2000_deg: 34.40, colour: '#d8a066', fact: 'Its Great Red Spot is a storm wider than Earth.' },
  { name: 'Saturn', type: 'planet', radius_km: 58232, distance_au: 9.537, orbital_period_days: 10759.22, rotation_period_hours: 10.66, axial_tilt_deg: 26.73, longitude_j2000_deg: 49.94, colour: '#e3c98b', fact: 'It is less dense than water.' },
  { name: 'Uranus', type: 'planet', radius_km: 25362, distance_au: 19.19, orbital_period_days: 30688.5, rotation_period_hours: -17.24, axial_tilt_deg: 97.77, longitude_j2000_deg: 313.23, colour: '#9fd8e0', fact: 'It spins on its side, tilted almost 98 degrees.' },
  { name: 'Neptune', type: 'planet', radius_km: 24622, distance_au: 30.07, orbital_period_days: 60182, rotation_period_hours: 16.11, axial_tilt_deg: 28.32, longitude_j2000_deg: 304.88, colour: '#4166f5', fact: 'Its winds are the fastest in the Solar System, over 2,000 km/h.' },
];
nb.set('bodies', bodies);

const years = (days) => (days / 365.26 >= 1 ? (days / 365.26).toFixed(1) + ' years' : Math.round(days) + ' days');
const rows = bodies.filter((b) => b.type === 'planet').map((b) => `
  <tr>
    <td><span class="dot" style="background:${b.colour}"></span>${b.name}</td>
    <td>${b.radius_km.toLocaleString()} km</td>
    <td>${b.distance_au} AU</td>
    <td>${years(b.orbital_period_days)}</td>
    <td>${b.axial_tilt_deg}°</td>
  </tr>`).join('');

return `
<style>
  .card { background: #0f172a; color: #e2e8f0; font: 14px/1.5 system-ui, sans-serif; border-radius: 12px; padding: 14px 18px; }
  table { width: 100%; border-collapse: collapse; }
  th { text-align: left; color: #94a3b8; font-weight: 600; font-size: 12px; padding: 4px 10px 6px 0; }
  td { padding: 5px 10px 5px 0; border-top: 1px solid #1e293b; }
  .dot { display: inline-block; width: 11px; height: 11px; border-radius: 50%; margin-right: 8px; vertical-align: -1px; }
</style>
<div class="card">
  <table>
    <tr><th>Planet</th><th>Radius</th><th>From the Sun</th><th>One orbit</th><th>Tilt</th></tr>
    ${rows}
  </table>
</div>`;

{
  "title": "Solar System controls",
  "width": 900,
  "height": 84,
  "controls": [
    { "type": "slider", "label": "Speed", "bind": "days_per_second", "default": 10, "min": 0, "max": 120, "step": 1, "suffix": " days/s", "x": 0, "y": 0, "width": 260, "height": 64 },
    { "type": "checkbox", "label": "Orbits", "bind": "show_orbits", "default": true, "x": 280, "y": 14, "width": 110, "height": 42 },
    { "type": "checkbox", "label": "Labels", "bind": "show_labels", "default": true, "x": 400, "y": 14, "width": 110, "height": 42 },
    {
      "type": "select", "label": "Follow", "bind": "follow", "default": "none",
      "options": ["none", "Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"],
      "x": 530, "y": 0, "width": 200, "height": 64
    },
    { "type": "button", "label": "Reset view", "icon": "fa-rotate-left", "bind": "reset_view", "action": "increment", "x": 750, "y": 14, "width": 150, "height": 42 }
  ]
}
